\documentclass[border=10pt]{standalone}
\usepackage{tikz}
\usetikzlibrary{positioning, shadows}

\begin{document}

\begin{tikzpicture}[
    auto,
    node distance=2.5cm and 3cm, % 垂直和水平间距
    thick,
    main/.style={
        circle, 
        draw, 
        fill=blue!10, 
        very thick, 
        minimum size=1cm, 
        font=\bfseries\large,
        drop shadow
    },
    weight/.style={
        font=\small\bfseries, 
        fill=white, 
        inner sep=2pt, 
        text=black
    },
    % 定义红色高亮边的样式
    mst/.style={
        draw=red, 
        line width=2pt
    }
]

    % -- 节点 (Nodes) --
    \node[main] (A) at (0, 1.5) {A};

    \node[main] (B) at (3, 3) {B};
    \node[main] (C) at (3, 0) {C};

    \node[main] (D) at (7, 3) {D};
    \node[main] (E) at (7, 0) {E};

    \node[main] (F) at (11, 3) {F};
    \node[main] (G) at (11, 0) {G};

    \node[main] (H) at (14, 1.5) {H};

    % -- 边 (Edges) --
    % 未选中的边保持黑色，选中的边使用 [mst] 样式变红

    % Layer 1
    \draw (A) -- node[weight] {10} (B);
    \draw[mst] (A) -- node[weight] {5} (C);  % Selected

    % Layer 2
    \draw (B) -- node[weight] {12} (C);
    \draw[mst] (B) -- node[weight] {4} (D);  % Selected
    \draw[mst] (C) -- node[weight, near start] {8} (D); % Selected
    \draw[mst] (C) -- node[weight] {3} (E);  % Selected

    % Layer 3
    \draw (D) -- node[weight, near end] {15} (E);
    \draw[mst] (D) -- node[weight] {6} (F);  % Selected
    \draw (E) -- node[weight, near start] {8} (F);
    \draw[mst] (E) -- node[weight] {7} (G);  % Selected

    % Layer 4
    \draw (F) -- node[weight] {9} (G);
    \draw (F) -- node[weight] {11} (H);
    \draw[mst] (G) -- node[weight] {2} (H);  % Selected

\end{tikzpicture}

\end{document}
